"""Coupled-class tables, refinement evidence and fast-candidate certificates."""
from common4 import *
from make_article import table,G,F,A
from figure_style import journal_layout
import numpy as np,pandas as pd,matplotlib.pyplot as plt

def main():
    f=pd.read_csv(ROOT/'results/joint_refinement/cases.csv');f['optimality_gap_Wh']=np.maximum(0,f.radius_upper_Wh-f.radius_lower_Wh);cert=pd.read_csv(ROOT/'results/joint_certificates/cases.csv');rows=[];numbers={};names={'coupled_calibration':'Time-varying','shared_affine':'Shared affine'}
    for model in names:
        numbers[model]={}
        for h in [0.,.5]:
            z=f[f.model.eq(model)&f.group.eq('full_primary')&f.halfwidth_s.eq(h)];assert len(z)==247;v={c:float(z[c].mean()) for c in ['old_RMSE_Wh','unrefined_RMSE_Wh','RMSE_Wh','old_radius_Wh','radius_upper_Wh','radius_lower_Wh','uniform_temporal_floor_Wh','evaluator_only_exact_anchor_floor_Wh','optimality_gap_Wh']};v['solver_counts']=z.shape_solver_mode.value_counts().to_dict();v['maximum_gap_Wh']=float(z.optimality_gap_Wh.max());numbers[model][str(h)]=v;rows.append([names[model],f'{h:g}',f'{v["old_radius_Wh"]:.4f}',f'{v["radius_upper_Wh"]:.4f}',f'{v["uniform_temporal_floor_Wh"]:.4f}',f'{v["old_RMSE_Wh"]:.4f}',f'{v["RMSE_Wh"]:.4f}'])
    table('joint_primary.tex','Post-development joint-model comparisons on all 247 retained records per row, B8/full, 4000 W. Bounds, floor and continuous RMSE are in Wh. Rectangular and joint methods receive identical readings and bounded PCHIP prior within each row. The two model families use different declared sensor mechanisms. Exact-time and inflated nominal-time rows have different class interpretations. Error uses the scale-aware shape refinement; original QP outcomes remain retained.',['Class','$h$','Rect. $R$','Joint upper','Temporal floor','Rect. error','Joint error'],rows,label='tab:jointprimary')
    s=pd.read_csv(ROOT/'results/joint_certificates/summary.csv');rows=[]
    for z in s.itertuples():rows.append([names[z.model],f'{z.halfwidth_s:g}',f'{z.feasible_candidates}/247',f'{100*z.mean_relative_excess:.4f}',f'{100*z.maximum_relative_excess:.3f}',f'{z.mean_additive_excess_Wh:.6f}'])
    table('joint_certificates.tex','Candidate certificates for the unchanged fast rectangular clip, computed from joint-class LP lower bounds and continuous outer envelopes. Gap percentages bound suboptimality in the stated class; they are not empirical accuracy improvements. Means and maxima are over the same 247 records. These exploratory certificates use no dense reference values.',['Class','$h$','Feasible','Mean gap \\%','Max gap \\%','Mean gap Wh'],rows,label='tab:jointcertificates')
    rows=[]
    for model in names:
        z=f[f.model.eq(model)];original=pd.read_csv(ROOT/'results'/model/'cases.csv');modes=z.shape_solver_mode.value_counts();rows.append([names[model],len(z),int((~original.shape_QP_optimized).sum()),int(modes.get('continuous_L2_QP',0)),int(modes.get('weighted_node_L1_LP',0)),int(modes.get('checked_original',0))])
    table('joint_numerics.tex','Original strict energy-unit rejections versus the separately registered all-case numerical refinement. A rejected original shape QP retains its feasible minimax LP center. Refined L1 outputs are labeled node-weighted L1 surrogates; they are not claimed L2-optimal. Dense truth is never used for solver selection.',['Class','Cases','Original fallback','Refined L2','Refined L1','Original retained'],rows,label='tab:jointnumerics')
    rows=[];q=f.copy();q['budget']=q.budget.fillna(8).astype(int);q['grid_nodes']=q.grid_nodes.fillna(33).astype(int);q['delivery']=q.delivery.fillna('full');q['declared_drift_W']=q.declared_drift_W.fillna(-1);q['actual_drift_W']=q.actual_drift_W.fillna(-1)
    keys=['model','group','budget','delivery','horizon_fraction','halfwidth_s','grid_nodes','actual_drift_W','declared_drift_W']
    for key,z in q.groupby(keys):
        model,group,B,delivery,fraction,h,grid,actual,drift=key;label={'full_primary':'Primary','budget_loss':'Budget/loss','prefix':'Prefix','refinement':'Grid','drift_sensitivity':'Drift'}[group];rows.append(['TV' if model=='coupled_calibration' else 'SA',label,B,'F' if delivery=='full' else 'L',f'{fraction:g}',f'{h:g}',grid,'--' if drift<0 else f'{actual:g}/{drift:g}',len(z),f'{z.radius_upper_Wh.mean():.4f}',f'{z.RMSE_Wh.mean():.4f}'])
    assert len(rows)==36,len(rows)
    table('full_joint.tex','All joint-model condition summaries after the labeled numerical refinement. TV/SA: time-varying/shared-affine class; F/L: full/interior half-loss delivery; f: current-horizon fraction; G: uniform proposal node count; D: actual/declared residual drift in W, applicable to SA only; exact and underdeclared zero-drift conditions remain separate. Bound and error are Wh. Each prefix is an independent current-horizon retrospective audit, not a tested streaming query scheduler.',['Class','Condition','$B$','Del.','$f$','$h$','$G$','$D_a/D_d$','Records','Upper','RMSE'],rows,long=True,label='tab:fulljoint')
    early=json.loads((ROOT/'results/coupled_calibration/gate.json').read_text());shared=json.loads((ROOT/'results/shared_affine/gate.json').read_text());refine=json.loads((ROOT/'results/joint_refinement/gate.json').read_text());numbers.update(original_coupled_gate=early,original_shared_gate=shared,numerical_refinement=refine,certificates=s.to_dict('records'),max_refined_numerical_risk_excess_Wh=float(f.numerical_risk_excess_Wh.max()));write(A/'joint_numbers.json',numbers)
    primary=f[f.group.eq('full_primary')&f.halfwidth_s.eq(0)];text='Retaining calibration dependence changes the conditional radius only modestly in these primary settings. The joint LP brackets close numerically: the largest coarse-lower/continuous-upper difference is '+f'{f.optimality_gap_Wh.max():.3g} Wh across all 1,756 cases. This is a float64 result, not formal interval certification. '+'All correctly supplied cases remain within their reported risk ceilings. The common-calibration assumptions do not identify the true gain or bias. With actual residual drift 2 W but declared drift zero, all 24 exact-time subset transcripts remain feasible, yet nine exclude the numerical reference. The 0.5 s clock relaxation contains all 24 references under the same underdeclared drift. Thus compatibility alone does not validate the instrument assumptions, and a wider clock relaxation can mask this discrepancy.\\par\n'
    text+='The data-only temporal floors and evaluator-only exact-anchor floors separate missing temporal information from calibration uncertainty. They are conditional on the stated 4000 W cap and lack of additional verified dynamics; a tighter independently justified cap can change them. The oracle floor is not an available inference input.\\par\n'
    tv=s[s.model.eq('coupled_calibration')&s.halfwidth_s.eq(0)].iloc[0];sa=s[s.model.eq('shared_affine')&s.halfwidth_s.eq(0)].iloc[0]
    text+=f'The unchanged fast clip is jointly feasible on every primary record. Its mean certified relative suboptimality upper bounds are {100*tv.mean_relative_excess:.4f}\\% in the time-varying class and {100*sa.mean_relative_excess:.4f}\\% in the shared-affine class; worst-record bounds are {100*tv.maximum_relative_excess:.3f}\\% and {100*sa.maximum_relative_excess:.3f}\\%. These a posteriori bounds compare worst-case performance with a joint-class optimum, not true-reference RMSE. Clock-relaxed rows have larger certificate gaps and retain their own scope. The result supports fast clipping as a useful default in these tested contracts; the LP is an audit reference, rather than an empirically dominant replacement.\\par\n'
    text+=f'The original shape solves fall back on {early["shape_QP_fallbacks"]}/926 and {shared["shape_QP_fallbacks"]}/830 cases despite checked minimax feasibility. The all-case numerical refinement uses {refine["mode_counts"].get("continuous_L2_QP",0):,} continuous-L2 QP outputs and {refine["mode_counts"].get("weighted_node_L1_LP",0):,} explicitly labeled node-weighted-L1 outputs; {refine["mode_counts"].get("checked_original",0)} retain the original center. Maximum checked risk-tube excess is {f.numerical_risk_excess_Wh.max():.3g} Wh. Earlier negative QP and selector results are not replaced as if preregistered success. The full LP/shape cost is additional to the original clip and is not assigned its 6.32-fold speedup.\n'
    (G/'joint_interpretation.tex').write_text(text,encoding='utf-8')
    fig,axes=plt.subplots(1,2,figsize=(10,3.8));x=np.arange(2);barhandles=[]
    for shift,(field,label,color) in enumerate([('old_radius_Wh','Rectangular','#999999'),('radius_upper_Wh','Joint upper','#176f78'),('uniform_temporal_floor_Wh','Query-only floor','#a5522a'),('evaluator_only_exact_anchor_floor_Wh','Oracle floor','#587db3')]):
        vals=[numbers[m]['0.0'][field] for m in names];h=axes[0].bar(x+(shift-1.5)*.18,vals,.18,label=label,color=color);barhandles.append(h)
    axes[0].set(xticks=x,xticklabels=['Time-varying','Shared affine'],ylabel='Bound / floor (Wh)',title='Exact-time primary histories')
    for model,color in [('coupled_calibration','#176f78'),('shared_affine','#a5522a')]:
        z=cert[cert.model.eq(model)&cert.group.eq('full_primary')&cert.halfwidth_s.eq(0)];values=np.sort(100*z.relative_suboptimality_upper.to_numpy());axes[1].step(values,100*np.arange(1,len(z)+1)/len(z),where='post',label=names[model],color=color,lw=1.1)
    axes[1].set(xlabel='Certified fast-clip excess (%)',ylabel='Records (%)',title='A posteriori joint-class certificate',ylim=(0,102));axes[1].legend(loc='lower right',fontsize=8,frameon=False);handles,labels=axes[0].get_legend_handles_labels();fig.legend(handles,labels,loc='lower center',ncol=2,frameon=False,bbox_to_anchor=(.5,-.01),fontsize=8);journal_layout(fig);fig.tight_layout(rect=[0,.26,1,1]);fig.savefig(F/'joint_calibration_analysis.png');plt.close(fig);print(json.dumps(numbers,indent=2))

if __name__=='__main__':main()
